export type WordType = 'noun' | 'verb' | 'adjective' | 'adverb' | 'conjunction' | 'preposition' | 'phrase' | 'other';

// CEFR level a word is drawn from. Each level's study pool is exclusive —
// wordsForLevel(level) returns only words tagged exactly that level, not
// lower ones too. LEVEL_ORDER is still the canonical list/ordering of every
// known level, used for iteration (migration, sync) and the Settings
// dropdown, not for cumulative filtering.
export type Level = 'A1' | 'A2' | 'B1' | 'B2' | 'C1' | 'C2';
export const LEVEL_ORDER: Level[] = ['A1', 'A2', 'B1', 'B2', 'C1', 'C2'];

export interface Word {
  id: string;
  de: string;
  article?: 'der' | 'die' | 'das';
  plural?: string;
  // Verbs only, generated via scripts/generate-verb-forms.py (same
  // "pre-baked, not looked up live" reasoning as exercisePrompt) — the
  // 3rd-person-singular present ("er/sie/es ___") and simple-past/
  // Präteritum ("er/sie/es ___") forms, written the way they'd actually
  // appear in a sentence (separable-prefix verbs with the prefix split
  // off, e.g. "steht auf" not "aufsteht"). Absent until that script has
  // been run and applied for a given verb.
  thirdPerson?: string;
  pastTense?: string;
  // Perfect tense with its correct 3rd-person-singular auxiliary ("hat
  // ___" or "ist ___") — the tense actually shown during study (see
  // DailySessionFlow), since Perfekt (not Präteritum) is what's actually
  // used in spoken German for most verbs.
  perfectTense?: string;
  en: string;
  // Simplified Chinese gloss, parallel to `en` — added later via a batch
  // translation pass (scripts/translate-to-chinese.py), so absent for any
  // word that pass hasn't reached yet. glossFor() is the one place that
  // should read either of these two fields; everywhere else should call it
  // instead of reaching for `.en`/`.zh` directly.
  zh?: string;
  type: WordType;
  category?: string;
  level: Level;
  // Hand-curated set of ~220 common A1 words (numbers, question words,
  // days/months, core verbs/adjectives, family, everyday nouns, basic
  // adverbs/prepositions, greetings) — no frequency corpus exists for this
  // wordlist, so this is a reasonable approximation, not a ranked source.
  // Only meaningful for level 'A1'; see lib/practice.ts's
  // isBootstrapCopyWord and buildStudyWords.
  highFrequency?: boolean;
  // The round-1 translation exercise's English sentence — pre-generated
  // once (see scripts/generate-exercise-prompts.py) using only the word's
  // level's guaranteed-safe baseline vocabulary (every word in lower CEFR
  // levels, or A1's 220 high-frequency words for A1 itself), never an
  // individual learner's own in-level progress. This makes it static and
  // instant to show — no per-user AI call needed for this step — at the
  // cost of being the same sentence for every learner at this word (the
  // CORRECTED TRANSLATION that becomes the word's permanent example is
  // still built from each learner's own attempt, so that part stays
  // distinct). Absent for A1's high-frequency words (they never need one —
  // see isBootstrapCopyWord) and for any word not yet covered by a batch
  // run; lib/ai.ts's generateSentence is the live fallback.
  exercisePrompt?: string;
  // Simplified Chinese translation of exercisePrompt, from the same batch
  // pass as `zh` above — same absence rules as exercisePrompt itself, plus
  // "not translated yet" as a third reason it might be missing even when
  // exercisePrompt itself is present.
  exercisePromptZh?: string;
}

